from __future__ import annotations

import json
from typing import Any

from fastapi import HTTPException

from mlflow.entities.assessment import Feedback
from mlflow.entities.gateway_guardrail import GuardrailAction, GuardrailStage
from mlflow.gateway.providers.utils import send_request
from mlflow.types.chat import ChatCompletionRequest


class GuardrailViolation(Exception):
    """Exception raised when a guardrail blocks a request or response.

    The error message contains the guardrail name and the scorer's rationale (matching the
    pattern ``name.*rationale``). When no specific rationale is available the message defaults
    to ``"blocked"``.
    """

    def __init__(
        self,
        message: str | None = None,
        *,
        name: str | None = None,
        rationale: str | None = None,
    ):
        if message is None:
            rationale = rationale or "blocked"
            message = f"{name}: {rationale}" if name else rationale
        self.message = message
        super().__init__(message)


def _interpret_value(value: Any, rationale: str | None) -> tuple[bool, str | None]:
    """Interpret a scalar scorer value into a (passing, rationale) tuple.

    ``bool`` is checked before ``str`` and both before the ``TypeError`` fallback. Note that
    ``bool`` is a subclass of ``int``, so it must be handled first to avoid treating ``True`` /
    ``False`` as unsupported integer values.
    """
    if isinstance(value, bool):
        return value, rationale
    if isinstance(value, str):
        return value.strip().lower() == "yes", rationale
    raise TypeError(f"unexpected value type: {type(value).__name__}")


def _interpret_single(result: Any) -> tuple[bool, str | None]:
    if isinstance(result, Feedback):
        return _interpret_value(result.value, result.rationale)
    return _interpret_value(result, None)


class JudgeGuardrail:
    """Guardrail that uses a scorer to validate or sanitize gateway traffic."""

    def __init__(
        self,
        scorer: Any,
        stage: GuardrailStage,
        action: GuardrailAction,
        name: str,
        action_llm_url: str = None,
        action_endpoint_name: str = None,
    ):
        self.scorer = scorer
        self.stage = stage
        self.action = action
        self.name = name
        self.action_llm_url = action_llm_url
        self.action_endpoint_name = action_endpoint_name

    async def process_request(self, request: dict) -> dict:
        if self.stage != GuardrailStage.BEFORE:
            return request
        result = self.scorer(inputs=request)
        return await self._apply(result, request)

    async def process_response(self, request: dict, response: dict) -> dict:
        if self.stage != GuardrailStage.AFTER:
            return response
        result = self.scorer(outputs=response)
        return await self._apply(result, response)

    async def _apply(self, result: Any, payload: dict) -> dict:
        # A list of Feedback objects is passing only if every item is individually passing;
        # any failing item raises a GuardrailViolation regardless of the configured action.
        if isinstance(result, list):
            for item in result:
                passing, rationale = _interpret_single(item)
                if not passing:
                    raise GuardrailViolation(name=self.name, rationale=rationale)
            return payload

        passing, rationale = _interpret_single(result)
        if passing:
            return payload

        if self.action == GuardrailAction.VALIDATION:
            raise GuardrailViolation(name=self.name, rationale=rationale)
        return await self._sanitize(payload)

    async def _sanitize(self, payload: dict) -> dict:
        if self.action_llm_url is None:
            raise GuardrailViolation(
                f"Cannot sanitize payload for guardrail '{self.name}': action_llm_url is "
                "not configured."
            )

        sanitization_payload = {
            **payload,
            "response_format": {
                "type": "json_schema",
                "json_schema": {
                    "name": "sanitized_payload",
                    "strict": False,
                    "schema": ChatCompletionRequest.model_json_schema(),
                },
            },
        }

        try:
            response = await send_request(
                headers={},
                base_url=self.action_llm_url,
                path="",
                payload=sanitization_payload,
            )
        except HTTPException as e:
            raise GuardrailViolation(
                f"Sanitization request failed for guardrail '{self.name}': {e.detail}"
            )

        content = response["choices"][0]["message"]["content"]
        try:
            return json.loads(content)
        except (json.JSONDecodeError, TypeError):
            raise GuardrailViolation(
                f"Sanitization for guardrail '{self.name}' returned invalid JSON."
            )

    @classmethod
    def from_entity(cls, entity: Any, server_url: str = None) -> JudgeGuardrail:
        from mlflow.genai.judges.instructions_judge import InstructionsJudge
        from mlflow.genai.scorers import Scorer

        scorer = Scorer.model_validate(entity.scorer.serialized_scorer)

        if entity.action_endpoint_name is not None:
            action_endpoint_name = entity.action_endpoint_name
            action_llm_url = server_url
        else:
            action_endpoint_name = None
            action_llm_url = None

        if isinstance(scorer, InstructionsJudge) and scorer.model.startswith("gateway:/"):
            scorer._model = "openai:/" + scorer.model[len("gateway:/") :]
            scorer._base_url = f"{server_url}/gateway/mlflow/v1/chat/completions"

        return cls(
            scorer=scorer,
            stage=entity.stage,
            action=entity.action,
            name=entity.name,
            action_llm_url=action_llm_url,
            action_endpoint_name=action_endpoint_name,
        )
